// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GameDownloadResource) predicate.GameDownloadResource {
	return predicate.GameDownloadResource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GameDownloadResource) predicate.GameDownloadResource {
	return predicate.GameDownloadResource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GameDownloadResource) predicate.GameDownloadResource {
	return predicate.GameDownloadResource(sql.NotPredicates(p))
}
